head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > groupbyZone]<br/>GridView 컴포넌트의 상단에 GroupBy Zone 을 표시할지 설정합니다.",
    "validation" : [
        "GroupBy Zone 에 Header Column 을 Drag&Drop 하면 ongroupby 이벤트가 발생하고 해당 이벤트에서 GroupBy 기능을 구현할 수 있습니다.",
        "true 설정 시, GroupBy Zone 을 GridView 컴포넌트의 상단에 표시합니다.",
        "false 설정 시, GroupBy Zone 을 GridView 컴포넌트에 표시하지 않습니다.",
        "미설정 시, GroupBy Zone 을 GridView 컴포넌트에 표시하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 셀렉트박스 초기값 : gdl_boolean 코드값 "2"(=true) 로 GroupBy Zone 표시 시연
    //  - 정적 select1 은 초기 selectedIndex 미적용이므로 onpageload 에서 명시 설정
    con_groupbyZone.setValue("2");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - con_groupbyZone : 공통 gdl_boolean → getText() ('' 미설정=속성제외 / 'true' / 'false')
//  - groupbyZone 은 렌더타임 속성이므로 con 변경 후 [Target 재생성](btn_createTarget→comp_init)으로만 반영
//  - groupbyZone=true 이면 엔진이 그리드 상단에 <div class='w2grid_groupbyZone' id='..._groupbyZone_div'> 를 렌더
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 값 : gdl_boolean 은 getText() 로 라벨('' / 'true' / 'false') 읽기
    let vGroupbyZone = con_groupbyZone.getText();

    // groupbyZone : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    let properties = {};
    if (vGroupbyZone === 'true') {
        properties.groupbyZone = true;
    } else if (vGroupbyZone === 'false') {
        properties.groupbyZone = false;
    }

    let lblDesc = '[전제] con 에서 groupbyZone 값 선택 후 [Target 재생성] 클릭 (현재: '
        + (vGroupbyZone === '' ? '(미설정)' : vGroupbyZone) + ')'
        + '\n[동작] groupbyZone=true 이면 그리드 상단에 GroupBy Zone 이 표시됨'
        + '\n[확인] [GroupBy Zone 표시 확인] 버튼으로 Zone DOM 존재 여부 확인'
        + '\n[관찰] 헤더 컬럼을 상단 GroupBy Zone 으로 드래그하면 ongroupby 발생(그룹핑)';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    let cList = $c.gcm.createCList(properties);

    // GridView 와 바인딩할 DataList 동적 생성 (4 Column, 6 Row : 그룹핑 시연용 중복 데이터)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (4컬럼 Body 그리드 + ongroupby 핸들러)
    await scwin.createGridView(cList);
}



// 그룹핑 시연용 데이터 (col1 에 중복값 → GroupBy 기준 컬럼으로 사용)
scwin.fillData = function () {
    let rows = [
        { col1: "서울", col2: "강남", col3: "A", col4: "100" },
        { col1: "서울", col2: "송파", col3: "B", col4: "200" },
        { col1: "부산", col2: "해운대", col3: "C", col4: "300" },
        { col1: "부산", col2: "수영", col3: "D", col4: "400" },
        { col1: "대구", col2: "수성", col3: "E", col4: "500" },
        { col1: "대구", col2: "달서", col3: "F", col4: "600" }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (ongroupby 이벤트 연결)
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' id="" dataList="data:dlt_bind" ev:ongroupby="scwin.target1_ongroupby" style="width:560px;height:480px;">';
    s += '<w2:caption style="" id="caption1" value="groupbyZone 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="140" style="" inputType="text" id="column1" value="지역"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="column2" value="상세"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="column3" value="구분"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="값"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="140" style="" inputType="text" id="col1"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col2"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// ongroupby : 헤더 컬럼을 GroupBy Zone 으로 드래그하면 발생 (@sample 패턴)
//  - options 에 groupbyHeader 를 정의한 뒤 groupby(options) 를 수동 호출해야 그룹핑이 적용됨
//  - 드래그는 사용자 조작 영역이므로 별도 실행 버튼은 두지 않고 이벤트 발생만 관찰/출력
scwin.target1_ongroupby = function (options) {
    options.groupbyHeader = [
        {colSpan: 4, inputType: 'expression', expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ", align: 'left'}
    ];
    options.hideFooter = true;

    target1.groupby(options);

    wf_body_bottom.getObj("scwin").setReturnValue("[ongroupby 발생] GroupBy 가 적용되었습니다.");
}



// depth 계층 가시화 들여쓰기 : depth×2칸 순수 공백 (depth_0 은 0칸, 깊을수록 2칸씩 누적)
scwin._depthMark = function (depth) {
    return "  ".repeat(depth);
};



// 확인 : (1) GroupBy Zone 표시 실측 + (2) 현재 그리드 표시값 화면순서 출력 을 한 번에 출력
//  (1) GroupBy Zone : groupbyZone=true 이면 상단에 Zone DOM(w2grid_groupbyZone, div[id$='_groupbyZone_div'])이 렌더됨
//      → Zone div 존재 여부 + 현재 groupbyZone 적용값 + 그룹 적용(grouped) 여부 실측
//  (2) 화면 표시 순서 : tbody 에 렌더된 Row 를 화면 순서(위→아래) 그대로 순회
//      - 그룹핑 상태면 그룹행/데이터행이 그 순서대로 반영, 그룹핑 전이면 평평한 데이터 순서
//      - 각 Row : 표시 셀 textContent 를 ' | ' 로 이어붙이고 Row 간 \n, depth 기준 들여쓰기
//      - 숨김 filler Row 제외, colSpan 누적으로 전체 컬럼(4) 도달 시 종료(phantom 빈 td 제외)
scwin.btn_check_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // (1) GroupBy Zone 표시 실측
    let zone = document.querySelector("div[id$='_groupbyZone_div']");
    let grouped = (target1.groupbyStatus && target1.groupbyStatus.sortIndexArr
        && target1.groupbyStatus.sortIndexArr.length > 0);
    bottom.setReturnValue("[GroupBy Zone] 적용값=" + target1.options.groupbyZone
        + " / Zone 표시=" + (zone !== null ? "표시됨" : "표시안됨")
        + " / 그룹 적용=" + (grouped ? "적용됨(" + target1.groupbyStatus.sortIndexArr.length + " Depth)" : "미적용"));

    // (2) 화면 표시 순서 출력
    let colCnt = 4;   // Body 컬럼 수(col1~col4)
    // 그룹핑된 depth 수 (그룹핑 전이면 0) → 데이터 행 들여쓰기 기준
    let depthCount = (target1.groupbyStatus && target1.groupbyStatus.sortIndexArr)
        ? target1.groupbyStatus.sortIndexArr.length : 0;

    let tbody = document.getElementById(target1.id + "_body_tbody");
    let trs = tbody ? tbody.querySelectorAll("tr") : [];
    let screenLines = [];

    for (let i = 0; i < trs.length; i++) {
        let tr = trs[i];
        // 데이터보다 많은 Row Slot 은 숨김 filler Row (w2grid_hidedRow, display:none) → 제외
        if (tr.style.display === "none" || tr.className.indexOf("w2grid_hidedRow") >= 0) {
            continue;
        }
        // 화면 표시 순서 그대로 : colSpan 을 누적해 컬럼 수 도달 시 종료(phantom 빈 td 제외)
        let cells = [];
        let colAcc = 0;
        let tdList = tr.querySelectorAll("td");
        for (let k = 0; k < tdList.length && colAcc < colCnt; k++) {
            let td = tdList[k];
            if (td.style.display === "none") continue;
            colAcc += parseInt(td.getAttribute("colSpan") || "1", 10);
            cells.push((td.textContent || "").replace(/ /g, " ").trim());
        }
        // 행 depth : 그룹 td(w2grid_groupby_depth_N) 있으면 그 N, 없으면 데이터 행 → depthCount
        let rowDepth = depthCount;
        let gtd = tr.querySelector("td[class*='w2grid_groupby_depth_']");
        if (gtd) {
            let m = gtd.className.match(/w2grid_groupby_depth_(\d+)/);
            if (m) rowDepth = parseInt(m[1], 10);
        }
        screenLines.push(scwin._depthMark(rowDepth) + cells.join(" | "));
    }

    bottom.setReturnValue("[화면 표시 순서]\n" + (screenLines.length ? screenLines.join("\n") : "(표시 Row 없음)"));
}
